// Which Host headers a local server answers: the guard against DNS rebinding.
//
// A page on a hostile domain that resolves to 127.0.0.1 is, to the browser, same-origin with that domain, so it can
// read whatever a local server answers. It cannot make the browser send "Host: localhost", though, so a server that
// answers only the names it is really reached by is safe. Bound to a loopback address, that is localhost, 127.0.0.1
// and [::1] (any port). Bound to another address, that address too (for 0.0.0.0 or ::, every address of this
// machine's network interfaces), plus the names in an explicit allowlist (DASHBOARD_ALLOWED_HOSTS or
// STUDIO_ALLOWED_HOSTS, comma-separated: a DNS name other machines use, or a reverse proxy's name). Everything else gets 403, before any route runs.
import { networkInterfaces } from 'node:os';

const LOOPBACK = ['localhost', '127.0.0.1', '::1'];

/** The host name of a Host header, lower-case, without port, brackets or a trailing dot. '' when there is none. */
export function hostName(header) {
  let h = String(header ?? '').trim().toLowerCase();
  if (!h) return '';
  if (h.startsWith('[')) { const end = h.indexOf(']'); return end > 0 ? h.slice(1, end) : ''; }
  // One colon is a port; more than one is a bare IPv6 address (no port possible without brackets).
  if ((h.match(/:/g) ?? []).length === 1) h = h.slice(0, h.indexOf(':'));
  return h.replace(/\.$/, '');
}

const isLoopback = (a) => a === '::1' || /^(::ffff:)?127\./.test(a);
const isWildcard = (a) => a === '0.0.0.0' || a === '::' || a === '::ffff:0.0.0.0';

/** The names a server bound to `address` answers, plus `extra` (a comma-separated allowlist). */
export function allowedHosts(address, extra = '') {
  const names = new Set(LOOPBACK);
  const a = String(address ?? '').toLowerCase().replace(/^::ffff:(?=\d)/, '');
  if (a && !isLoopback(a)) {
    // The wildcard itself is no name anyone reaches a server by (and some browsers send it for loopback).
    if (!isWildcard(a)) names.add(a);
    else {
      for (const list of Object.values(networkInterfaces())) for (const i of list ?? []) names.add(i.address.toLowerCase().replace(/%.*$/, ''));
    }
  }
  for (const n of String(extra ?? '').split(',')) { const h = hostName(n); if (h) names.add(h); }
  return names;
}

/**
 * A check for one server: guard(req) is true when the request's Host header names this server. The allowed names
 * are worked out from the address the server is listening on, the first time a request comes in.
 */
export function hostGuard(server, extra = '') {
  let names = null;
  return (req) => {
    names ??= allowedHosts(server.address()?.address, extra);
    return names.has(hostName(req.headers.host));
  };
}
